def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    marker = min(colors, key=lambda v: sum(row.count(v) for row in grid))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    out = [row[:] for row in grid]

    # The shape is stamped at zero-valued anchor cells; existing nonzero
    # cells are left untouched.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                for dr, dc in shape:
                    rr, cc = r + dr, c + dc
                    if rr < h and cc < w and grid[rr][cc] == 0:
                        out[rr][cc] = marker
    return out
