def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return [row[:] for row in grid]
    color = min(counts, key=counts.get)
    out = [row[:] for row in grid]

    # The colored object marks the size of the repeated patches: paint
    # empty 3-by-3 patches with its color.
    for r in range(h - 2):
        for c in range(w - 2):
            if all(grid[i][j] == 0
                   for i in range(r, r + 3)
                   for j in range(c, c + 3)):
                for i in range(r, r + 3):
                    for j in range(c, c + 3):
                        out[i][j] = color
    return out
